    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // Based on implementation: len = 0, max = str.length(). 
        // Loop condition i == max will only execute if str is empty and searchStr is empty.
        // If str is "a", len=0, max=1. Loop i=0; 0==1 is false. Returns false.
        // If str is "", len=0, max=0. Loop i=0; 0==0 is true. regionMatches returns true.
        assertTrue(StringUtils.containsIgnoreCase("", ""));
        assertFalse(StringUtils.containsIgnoreCase("abc", ""));
    }






}

