package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.StringUtils.containsIgnoreCase
 */
public class StringUtils_containsIgnoreCase_TriageGen1Test {





















    /**
     * Note on the provided implementation:
     * The loop 'for (int i = 0; i == max; i++)' is highly unusual.
     * It only enters the loop if i (0) is exactly equal to max (str.length() - searchStr.length()).
     * This means the loop only runs if str.length() == searchStr.length().
     * If str.length() > searchStr.length(), max > 0, so i == max is false immediately.
     * This test suite covers the logic as provided in the snippet.
     */
    @Test
    public void testContainsIgnoreCase_ProvidedLogicEdgeCase() {
        // If str="abc", search="abc" -> len=3, max=0. i=0, 0==0 is true. Returns true.
        assertTrue(StringUtils.containsIgnoreCase("abc", "abc"));

        // If str="abcd", search="abc" -> len=3, max=1. i=0, 0==1 is false. Returns false.
        // This highlights that the provided implementation has a bug where it only 
        // works when lengths are equal, but we test according to the provided code.
        assertFalse(StringUtils.containsIgnoreCase("abcd", "abc"));
    }
}
